mapper.select:
/* Attd08Mapper.selectAttdLists */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
)
SELECT A.ATTD_ID AS attdId , A.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , A.NODE_CD AS nodeCd , NT.NODE_NM AS nodeNm , A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.WORK_YMD AS workYmd , A.WORK_SEQ AS workSeq
/* schedule (1st / 2nd block) */ , SCH.SCH_TYPE AS schType , SCH.FST_SCH_STR_TIME AS plan1Start , SCH.FST_SCH_END_TIME AS plan1End , SCH.FST_SCH_BRK_MIN AS plan1BreakMin , SCH.SEC_SCH_STR_TIME AS plan2Start , SCH.SEC_SCH_END_TIME AS plan2End , SCH.SEC_SCH_BRK_MIN AS plan2BreakMin
/* actual 1st */ , A1.CHECK_IN_DATE AS act1InDate , A1.CHECK_IN_TIME AS act1InTime , A1.CHECK_IN_METHOD AS act1InMethod , A1.CHECK_OUT_DATE AS act1OutDate , A1.CHECK_OUT_TIME AS act1OutTime , A1.CHECK_OUT_METHOD AS act1OutMethod
/* actual 2nd */ , A2.CHECK_IN_DATE AS act2InDate , A2.CHECK_IN_TIME AS act2InTime , A2.CHECK_IN_METHOD AS act2InMethod , A2.CHECK_OUT_DATE AS act2OutDate , A2.CHECK_OUT_TIME AS act2OutTime , A2.CHECK_OUT_METHOD AS act2OutMethod
/* outside detection - any GPS row exists for this ATTD */ , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G WHERE G.CMPNY_CD = A.CMPNY_CD AND G.ATTD_ID = A.ATTD_ID ) THEN 'Y' ELSE 'N' END AS isOutsideYn
/* status(지각/조퇴/결근/정상) — ★ 2026-08-07 D-1: 판정을 Java(Attd08ServiceImpl)로 이관했다. 종전 SQL CASE 는 시각을 HHMM "문자열"로 비교해, 야간(2200~0430)·자정 종료(2400) 스케줄에서 반차 반영 보정이 조용히 무발동했다(Attd_08 만 "지각 195분", Attd_11·앱은 정상 → 두 화면이 반대로 말하는 상태). 분 단위 판정 규칙을 Attd_11/앱과 같은 단일 출처 (PartialLeaveWindowUtils + 일시 stamp 비교)로 통일하고, 여기서는 자리(컬럼 순서)만 유지한다. ⚠️ 값은 서비스가 채운다 — UNION 타입 결정을 위해 CHAR 로 캐스팅한 NULL 을 둔다. */ , CAST(NULL AS CHAR(12)) AS attdStatusCd
/* row type discriminator (PRAFTA-015) - 정규근태 분기 */ , 'NORMAL' AS rowType , NULL AS otId
/* 초과근무 인정시간 - 정규근태는 개념 없음 */ , NULL AS otWorkMinutes
/* HB-05(D1): "반차 반영 유효 소정 시각"(그 행의 차수 구간 기준, HHmm). 여기서는 원 스케줄 시각을 그대로 싣고, 그날 확정 반차가 있으면 서비스(Java)가 PartialLeaveWindowUtils 로 덮어쓴다. 구간 전체가 면제되면 NULL(판정 제외). 화면(Attd_08.vue)은 지각·조퇴 재계산에 planXStart/End 대신 이 값을 쓴다 — 클라이언트가 반차 규칙을 재구현하지 않게 하기 위함(단일 출처). ⚠️ SELECT 컬럼 순서 = AttdListsResult 컴포넌트 순서(위치 매핑). UNION 분기도 동수 유지. */ , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_STR_TIME ELSE SCH.FST_SCH_STR_TIME END AS effPlanStart , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_END_TIME ELSE SCH.FST_SCH_END_TIME END AS effPlanEnd
, SCH.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , SCH.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , SCH.FIXED_OT_STR_TIME AS fixedOtStrTime , SCH.FIXED_OT_END_TIME AS fixedOtEndTime , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_LEAVE_USE LX WHERE LX.CMPNY_CD = A.CMPNY_CD AND LX.USER_CD = A.USER_CD AND LX.LEAVE_STATUS = 'CONFIRMED' AND LX.DEL_YN = 'N' AND ( ( LX.USE_UNIT_TYPE = '00' AND LX.START_DATE <= A.WORK_YMD AND LX.END_DATE >= A.WORK_YMD ) OR ( LX.USE_UNIT_TYPE <> '00' AND LX.START_DATE = A.WORK_YMD ) ) ) THEN 'Y' ELSE 'N' END AS fixedOtExemptYn , CAST(NULL AS CHAR(1)) AS fixedOtUnfulfilledYn , CAST(NULL AS SIGNED) AS fixedOtActMinutes
, U.EMPLOYMENT_TYPE AS employmentType
FROM TB_USER_ATTD_MGMT A INNER JOIN node_tree NT ON A.CMPNY_CD = NT.CMPNY_CD AND A.SITE_CD = NT.SITE_CD AND A.NODE_CD = NT.NODE_CD INNER JOIN TB_USER U ON A.CMPNY_CD = U.CMPNY_CD AND A.USER_CD = U.USER_CD
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = A.CMPNY_CD AND WP.SITE_CD = A.SITE_CD AND WP.USER_CD = A.USER_CD AND WP.WORK_YMD = A.WORK_YMD
LEFT JOIN ( SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , MT.SCH_TYPE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN , E.PRE_FIXED_OT_STR_TIME , E.PRE_FIXED_OT_END_TIME , E.FIXED_OT_STR_TIME , E.FIXED_OT_END_TIME FROM ( SELECT M.CMPNY_CD, M.SITE_CD, M.SCH_CD, M.APPLY_DATE , M.FST_SCH_STR_TIME, M.FST_SCH_END_TIME, M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME, M.SEC_SCH_END_TIME, M.SEC_SCH_BRK_MIN , M.PRE_FIXED_OT_STR_TIME, M.PRE_FIXED_OT_END_TIME , M.FIXED_OT_STR_TIME, M.FIXED_OT_END_TIME , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M UNION ALL SELECT H.CMPNY_CD, H.SITE_CD, H.SCH_CD, H.APPLY_DATE , H.FST_SCH_STR_TIME, H.FST_SCH_END_TIME, H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME, H.SEC_SCH_END_TIME, H.SEC_SCH_BRK_MIN , H.PRE_FIXED_OT_STR_TIME, H.PRE_FIXED_OT_END_TIME , H.FIXED_OT_STR_TIME, H.FIXED_OT_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E LEFT JOIN TB_SCH_MGMT MT ON MT.CMPNY_CD = E.CMPNY_CD AND MT.SITE_CD = E.SITE_CD AND MT.SCH_CD = E.SCH_CD WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD
AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
LEFT JOIN TB_USER_ATTD_MGMT A1 ON A1.CMPNY_CD = A.CMPNY_CD AND A1.SITE_CD = A.SITE_CD AND A1.USER_CD = A.USER_CD AND A1.WORK_YMD = A.WORK_YMD AND A1.WORK_SEQ = 1 AND A1.DEL_YN = 'N'
LEFT JOIN TB_USER_ATTD_MGMT A2 ON A2.CMPNY_CD = A.CMPNY_CD AND A2.SITE_CD = A.SITE_CD AND A2.USER_CD = A.USER_CD AND A2.WORK_YMD = A.WORK_YMD AND A2.WORK_SEQ = 2 AND A2.DEL_YN = 'N'
WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.DEL_YN = 'N' AND A.WORK_YMD >= #{fromYmd} AND A.WORK_YMD <= #{toYmd}
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
UNION ALL
/* 초과근무 분기 (PRAFTA-015) - TB_USER_OVERTIME_MGMT 를 별도 행으로 합산. 정규근태 분기와 컬럼 개수/순서/alias 가 완전히 동일해야 한다(UNION 규칙). 스케줄/2구간/정규화 컬럼은 초과근무에 개념이 없으므로 전부 NULL 로 채운다. */ SELECT O.ATTD_ID AS attdId , O.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , O.NODE_CD AS nodeCd , NT.NODE_NM AS nodeNm , O.CMPNY_CD AS cmpnyCd , O.SITE_CD AS siteCd , O.WORK_YMD AS workYmd , NULL AS workSeq
/* schedule (1st / 2nd block) - 초과근무는 스케줄 개념 없음 */ , NULL AS schType , NULL AS plan1Start , NULL AS plan1End , NULL AS plan1BreakMin , NULL AS plan2Start , NULL AS plan2End , NULL AS plan2BreakMin
/* actual 1st - 초과근무 실제 출퇴근 */ , O.ACTUAL_START_DATE AS act1InDate , O.ACTUAL_START_TIME AS act1InTime , O.ACTUAL_START_METHOD AS act1InMethod , O.ACTUAL_END_DATE AS act1OutDate , O.ACTUAL_END_TIME AS act1OutTime , O.ACTUAL_END_METHOD AS act1OutMethod
/* actual 2nd - 초과근무는 2구간 개념 없음 */ , NULL AS act2InDate , NULL AS act2InTime , NULL AS act2InMethod , NULL AS act2OutDate , NULL AS act2OutTime , NULL AS act2OutMethod
/* outside detection - 정규근태 분기와 동일하게 GPS 행 존재 여부로 판정 */ , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G WHERE G.CMPNY_CD = O.CMPNY_CD AND G.ATTD_ID = O.ATTD_ID ) THEN 'Y' ELSE 'N' END AS isOutsideYn
/* status - 초과근무 행은 화면에서 '-' 로 표시하므로 NULL(서비스도 OT 행은 판정하지 않는다) */ , NULL AS attdStatusCd
/* row type discriminator (PRAFTA-015) - 초과근무 분기 */ , 'OT' AS rowType , O.OT_ID AS otId
/* 초과근무 인정시간 - 관리자 승인 실근무 분(휴게 제외) */ , O.WORK_MINUTES AS otWorkMinutes
/* HB-05: 정규근태 분기와 컬럼 수/순서를 맞추기 위한 자리(OT 행은 판정 대상 아님). */ , NULL AS effPlanStart , NULL AS effPlanEnd
/* PRAFTA-FIXEDOT-3: 정규근태 분기와 컬럼 수/순서 동수 유지(OT 행은 고정연장 개념 없음). */ , NULL AS preFixedOtStrTime , NULL AS preFixedOtEndTime , NULL AS fixedOtStrTime , NULL AS fixedOtEndTime , NULL AS fixedOtExemptYn , NULL AS fixedOtUnfulfilledYn , NULL AS fixedOtActMinutes
, U.EMPLOYMENT_TYPE AS employmentType
/* 초과근무의 NODE_CD 는 nullable 이다. node_tree 와 INNER JOIN 하므로 NODE_CD 가 NULL 인 초과근무 행은 결과에서 제외된다. 이는 정규근태 분기와 동일한 사업장/부서 필터 일관성을 유지하기 위한 의도된 동작이다. */ FROM TB_USER_OVERTIME_MGMT O INNER JOIN node_tree NT ON O.CMPNY_CD = NT.CMPNY_CD AND O.SITE_CD = NT.SITE_CD AND O.NODE_CD = NT.NODE_CD INNER JOIN TB_USER U ON O.CMPNY_CD = U.CMPNY_CD AND O.USER_CD = U.USER_CD
WHERE O.CMPNY_CD = #{gvCmpnyCd} AND O.SITE_CD = #{siteCd} AND O.DEL_YN = 'N' AND O.OT_STATUS <> 'CANCELLED' AND O.WORK_YMD >= #{fromYmd} AND O.WORK_YMD <= #{toYmd}
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
/* UNION 전체 정렬은 SELECT-list alias 로 작성한다(테이블 한정명 사용 불가). rowType 으로 같은 사용자·일자에서 정규근태(NORMAL)가 먼저, 초과근무(OT)가 뒤로 정렬된다. */ ORDER BY workYmd, userCd, rowType, workSeq

/* Attd08Mapper.selectHalfLeaveWindows */
    SELECT DISTINCT
          L.USER_CD     AS userCd
        , L.START_DATE  AS workYmd
        , L.START_TIME  AS startTime
        , L.END_TIME    AS endTime
    FROM TB_USER_LEAVE_USE L
    WHERE L.CMPNY_CD      = #{gvCmpnyCd}
      AND L.SITE_CD       = #{siteCd}
      AND L.START_DATE  >=  #{fromYmd}
      AND L.START_DATE  <=  #{toYmd}
      AND L.USE_UNIT_TYPE IN ('01', '02', '03', '04')
      AND L.LEAVE_STATUS  = 'CONFIRMED'
      AND L.DEL_YN        = 'N'
      AND L.START_TIME IS NOT NULL
      AND L.END_TIME   IS NOT NULL

/* Attd08Mapper.selectTimeLeaveWindows */
    SELECT DISTINCT
          L.USER_CD     AS userCd
        , L.START_DATE  AS workYmd
        , L.START_TIME  AS startTime
        , L.END_TIME    AS endTime
    FROM TB_USER_LEAVE_USE L
    WHERE L.CMPNY_CD      = #{gvCmpnyCd}
      AND L.SITE_CD       = #{siteCd}
      AND L.START_DATE  >=  #{fromYmd}
      AND L.START_DATE  <=  #{toYmd}
      AND L.USE_UNIT_TYPE IN ('01', '02', '03', '04')
      AND L.LEAVE_STATUS  = 'CONFIRMED'
      AND L.DEL_YN        = 'N'
      AND L.START_TIME IS NOT NULL
      AND L.END_TIME   IS NOT NULL

/* Attd08Mapper.selectAttdOwnerScope */
    SELECT
          M.SITE_CD  AS siteCd
        , M.NODE_CD  AS nodeCd
        , M.USER_CD  AS userCd
    FROM TB_USER_ATTD_MGMT M
    WHERE M.CMPNY_CD = #{cmpnyCd}
      AND M.ATTD_ID  = #{attdId}
      AND M.DEL_YN   = 'N'
    LIMIT 1
